interface.signature:
interface DebtAccount {
  id?: number;
  name: string;
  type: AccountType;
  balance: string;
  interestRate: string;
  minimumPayment: string;
  lender: string;
  interestType: InterestType;
  createdAt: string;
  updatedAt: string;
}

interface UseAccountsReturn {
  accounts: DebtAccount[];
  isLoading: boolean;
  addAccount: (account: Omit<DebtAccount, 'id' | 'createdAt' | 'updatedAt'>) => Promise<Result<number>>;
  updateAccount: (id: number, updates: Partial<DebtAccount>) => Promise<Result<void>>;
  deleteAccount: (id: number) => Promise<Result<void>>;
  totalDebt: string;
  totalMinPayments: string;
}

type Result<T, E = Error> =
  | { success: true; data: T }
  | { success: false; error: E };
